  (623, 'E-000001', 'P-0001', 'admissao', 'Dr. Otavio Nunes (CRM 39104)', now() - interval '151 minutes', 'Homem de 68 anos, hipertenso e diabetico, com dor toracica opressiva iniciada ha 5 horas, irradiada para membro superior esquerdo, associada a sudorese. Nega sincope. Aguardando eletrocardiograma.'),
  (624, 'E-000002', 'P-0002', 'evolucao', 'Dr. Fabio Andrade (CRM 47003)', now() - interval '1628 minutes', 'Mulher de 74 anos com fibrilacao atrial anticoagulada, iniciou azitromicina ha dois dias por quadro respiratorio. Refere gengivorragia leve.'),
  (625, 'E-000003', 'P-0003', 'admissao', 'Dr. Ricardo Salles (CRM 28390)', now() - interval '900 minutes', 'Homem de 55 anos com pneumonia adquirida na comunidade, CURB-65 igual a 2, internado para antibioticoterapia endovenosa.'),
  (626, 'E-000004', 'P-0004', 'admissao', 'Dra. Helena Braga (CRM 41822)', now() - interval '403 minutes', 'Mulher de 81 anos com insuficiencia cardiaca e doenca renal cronica, admitida por piora do edema e dispneia aos minimos esforcos.'),
  (627, 'E-000005', 'P-0005', 'evolucao', 'Dr. Otavio Nunes (CRM 39104)', now() - interval '4173 minutes', 'Mulher de 30 anos com asma bem controlada, sem exacerbacao nos ultimos 12 meses. Tecnica inalatoria revisada em consulta.'),
