-- Prontuarios sinteticos
--
--   P-0001  dor toracica, troponina alterada e ECG ainda pendente
--   P-0002  em uso de varfarina, com INR alto
--   P-0003  alergia grave a penicilina, com penicilina ativa na prescricao
--   P-0004  insuficiencia cardiaca e doenca renal, potassio alto
--   P-0005  caso de rotina, sem nada fora do lugar
--
-- Todos os instantes sao RELATIVOS a now(), para o seed nao envelhecer: os
-- exames do P-0001 estao sempre pendentes ha 4 horas.

SET client_encoding = 'UTF8';

TRUNCATE clinical.pacientes RESTART IDENTITY CASCADE;

-- clinical.pacientes: 50 linhas

-- clinical.condicoes: 83 linhas
SELECT setval(pg_get_serial_sequence('clinical.condicoes', 'id'), COALESCE((SELECT MAX(id) FROM clinical.condicoes), 1));

-- clinical.alergias: 15 linhas
SELECT setval(pg_get_serial_sequence('clinical.alergias', 'id'), COALESCE((SELECT MAX(id) FROM clinical.alergias), 1));

-- clinical.encontros: 138 linhas

-- clinical.sinais_vitais: 138 linhas
SELECT setval(pg_get_serial_sequence('clinical.sinais_vitais', 'id'), COALESCE((SELECT MAX(id) FROM clinical.sinais_vitais), 1));

-- clinical.exames: 361 linhas

-- clinical.resultados_exame: 327 linhas
SELECT setval(pg_get_serial_sequence('clinical.resultados_exame', 'id'), COALESCE((SELECT MAX(id) FROM clinical.resultados_exame), 1));

-- clinical.prescricoes: 291 linhas

-- clinical.notas_clinicas: 138 linhas
SELECT setval(pg_get_serial_sequence('clinical.notas_clinicas', 'id'), COALESCE((SELECT MAX(id) FROM clinical.notas_clinicas), 1));



SELECT setval(pg_get_serial_sequence('clinical.consultas', 'id'),
              COALESCE((SELECT MAX(id) FROM clinical.consultas), 1));
